      this._writer.writeVariableText(state.name);
      this._writer.writeBitLong(state.entities.length);
      for (const entity of state.entities)
        this._writer.handleReferenceTyped(DwgReferenceType.SoftPointer, entity);
      this._writer.writeBitLong(state.expressions.length);
      for (const expression of state.expressions)
        this._writer.handleReferenceTyped(DwgReferenceType.SoftPointer, expression);
